    TimerAst2400V1TMCCTRL2T3SEQSTARTPos = 10
    TimerAst2400V1TMCCTRL2T3SEQSTARTMsk = 0x1 << 10
    // T4SEQSTART TMC34[11]: Timer 4 sequence pulse start counting.
    TimerAst2400V1TMCCTRL2T4SEQSTARTPos = 11
    TimerAst2400V1TMCCTRL2T4SEQSTARTMsk = 0x1 << 11
    // T5SEQSTART TMC34[12]: Timer 5 sequence pulse start counting.
    TimerAst2400V1TMCCTRL2T5SEQSTARTPos = 12
    TimerAst2400V1TMCCTRL2T5SEQSTARTMsk = 0x1 << 12
    // T6SEQSTART TMC34[13]: Timer 6 sequence pulse start counting.
    TimerAst2400V1TMCCTRL2T6SEQSTARTPos = 13
    TimerAst2400V1TMCCTRL2T6SEQSTARTMsk = 0x1 << 13
    // T7SEQSTART TMC34[14]: Timer 7 sequence pulse start counting.
    TimerAst2400V1TMCCTRL2T7SEQSTARTPos = 14
    TimerAst2400V1TMCCTRL2T7SEQSTARTMsk = 0x1 << 14
