    TimerAst2400V1TMCCTRL2T3SEQINITPos = 18
    TimerAst2400V1TMCCTRL2T3SEQINITMsk = 0x1 << 18
    // T4SEQINIT TMC34[19]: Timer 4 sequence pulse initial output value.
    TimerAst2400V1TMCCTRL2T4SEQINITPos = 19
    TimerAst2400V1TMCCTRL2T4SEQINITMsk = 0x1 << 19
    // T5SEQINIT TMC34[20]: Timer 5 sequence pulse initial output value.
    TimerAst2400V1TMCCTRL2T5SEQINITPos = 20
    TimerAst2400V1TMCCTRL2T5SEQINITMsk = 0x1 << 20
    // T6SEQINIT TMC34[21]: Timer 6 sequence pulse initial output value.
    TimerAst2400V1TMCCTRL2T6SEQINITPos = 21
    TimerAst2400V1TMCCTRL2T6SEQINITMsk = 0x1 << 21
