    UartV1IERERBFIMsk = 0x1 << 0
    // ETBEI Enable Transmitter Holding Register Empty Interrupt. 1 = generate IRQ when THR is empty (LSR.THRE=1).
    UartV1IERETBEIPos = 1
    UartV1IERETBEIMsk = 0x1 << 1
